const state = $('Get Paper State').first().json;
const trades = $input.all().map(function(i){ return i.json; }).filter(function(t){ return t && typeof t.netPnl === 'number'; });
const returnPct = (state.equity - 100) / 100 * 100;
const totalTrades = trades.length;
const wins = trades.filter(function(t){ return t.netPnl > 0; }).length;
const losses = totalTrades - wins;
const winRate = totalTrades > 0 ? (wins/totalTrades*100) : 0;
const now = new Date();
const dayMs = 24*60*60*1000;
const last24h = trades.filter(function(t){ return (now.getTime() - new Date(t.closedAt).getTime()) <= dayMs; });
const startDate = new Date('2026-09-20T00:00:00Z');
const targetLiveDate = new Date('2026-09-27T00:00:00Z');
const daysElapsed = Math.floor((now.getTime()-startDate.getTime())/dayMs);
const daysRemaining = Math.max(0, Math.ceil((targetLiveDate.getTime()-now.getTime())/dayMs));
const isLastDay = now.getTime() >= targetLiveDate.getTime();
const dateStr = now.toISOString().slice(0,10);
let rows = '';
const recent = trades.slice(0,15);
for (let i=0;i<recent.length;i++){ const t=recent[i]; rows += '<tr><td>'+t.closedAt+'</td><td>'+t.symbol+'</td><td>'+t.reason+'</td><td>'+t.entryPrice+'</td><td>'+t.exitPrice+'</td><td style="color:'+(t.netPnl>=0?'green':'red')+'">'+t.netPnl.toFixed(4)+'</td><td>'+t.equityAfter.toFixed(2)+'</td></tr>'; }
if (recent.length === 0) { rows = '<tr><td colspan="7" style="text-align:center;color:#777;">No trades closed yet</td></tr>'; }
const htmlReport = '<html><body style="font-family:Arial,sans-serif;font-size:13px;">' +
  '<h2>AI Trading Agent - Daily Report</h2>' +
  '<p><b>Date:</b> ' + dateStr + '</p>' +
  '<h3>Account Summary</h3>' +
  '<table border="1" cellpadding="6" cellspacing="0">' +
  '<tr><td>Starting Capital</td><td>$100.00</td></tr>' +
  '<tr><td>Current Equity</td><td>$' + state.equity.toFixed(2) + '</td></tr>' +
  '<tr><td>Peak Equity</td><td>$' + state.peakEquity.toFixed(2) + '</td></tr>' +
  '<tr><td>Total Return</td><td>' + returnPct.toFixed(2) + '%</td></tr>' +
  '<tr><td>Total Closed Trades</td><td>' + totalTrades + '</td></tr>' +
  '<tr><td>Wins / Losses</td><td>' + wins + ' / ' + losses + '</td></tr>' +
  '<tr><td>Win Rate</td><td>' + winRate.toFixed(1) + '%</td></tr>' +
  '<tr><td>Trades in Last 24h</td><td>' + last24h.length + '</td></tr>' +
  '<tr><td>Currently In Position</td><td>' + (state.inPosition ? ('YES - ' + state.symbol) : 'No') + '</td></tr>' +
  '<tr><td>Days Elapsed (Paper Phase)</td><td>' + daysElapsed + '</td></tr>' +
  '<tr><td>Days Remaining Until Live-Readiness Check</td><td>' + daysRemaining + '</td></tr>' +
  '</table>' +
  '<h3>Recent Trades</h3>' +
  '<table border="1" cellpadding="5" cellspacing="0"><tr><th>Closed At</th><th>Symbol</th><th>Reason</th><th>Entry</th><th>Exit</th><th>Net PnL</th><th>Equity After</th></tr>' + rows + '</table>' +
  '<p style="color:#777;font-size:11px;">Automated paper-trading report. No real funds are used until live execution is explicitly enabled.</p>' +
  '</body></html>';
const goLiveHtml = '<html><body style="font-family:Arial,sans-serif;font-size:14px;line-height:1.6;" dir="rtl">' +
  '<h2>وصلنا إلى نهاية أسبوع الاختبار الفني</h2>' +
  '<p>مرحباً، هذا إشعار بأن أسبوع التداول الورقي الفني قد اكتمل. الرصيد الحالي: <b>$' + state.equity.toFixed(2) + '</b> بعد ' + totalTrades + ' صفقة.</p>' +
  '<h3>الخطوات التالية لربط BingX الحقيقي (شرح مبسط):</h3>' +
  '<ol>' +
  '<li>سجّل دخولك لحساب BingX من المتصفح أو التطبيق.</li>' +
  '<li>اذهب إلى إعدادات الحساب ثم "API Management".</li>' +
  '<li>اضغط "Create API Key" وأنشئ مفتاحاً جديداً مخصصاً لهذا المشروع فقط.</li>' +
  '<li>عند الأذونات: فعّل "Spot Trading" فقط، وتأكد أن "Withdrawal" غير مفعّل إطلاقاً.</li>' +
  '<li>إن توفر خيار تقييد عنوان IP، فعّله لاحقاً بمساعدتي بعد معرفة IP الخاص بالخادم.</li>' +
  '<li>انسخ الـ API Key والـ Secret الظاهرين مرة واحدة فقط - احفظهما مؤقتاً في مكان آمن.</li>' +
  '<li>لا تُدخل هذين المفتاحين هنا أو في أي محادثة - سنضيفهما معاً مباشرة داخل خانة Credentials في n8n عندما تكون جاهزاً.</li>' +
  '</ol>' +
  '<p>راسلني في المحادثة عندما يكون المفتاح جاهزاً لديك.</p>' +
  '</body></html>';
return [{ json: { htmlReport: htmlReport, goLiveHtml: goLiveHtml, isLastDay: isLastDay, dateStr: dateStr, equity: state.equity, totalTrades: totalTrades } }];
